import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class StarterDeck100DistributedMoveTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    static void select(ServerMatch m,List<CardInstance> cards){var p=m.effectCardPrompt(A);m.submitEffectCards(A,p.resolutionId(),p.step(),cards.stream().map(CardInstance::instanceId).toList());}
    public static void main(String[] args){strafe();landorus();noBench();sandaconda();skip();pulse();System.out.println("StarterDeck100DistributedMoveTest passed: all/any Energy, independent destinations, simultaneous swaps, no Bench, host restrictions and forged/incomplete/replayed choices");}
    static void strafe(){for(boolean use:List.of(false,true)){var m=StarterDeck100PokemonTest.game(232);var old=m.activePokemonView(A).pokemonId();StarterDeck100PokemonTest.attack(m,0);var p=m.effectChoicePrompt(A);m.chooseEffectOption(A,p.resolutionId(),p.step(),use?0:1);if(use)StarterDeck100PokemonTest.choosePokemon(m,m.benchPokemonView(A).getFirst().pokemonId());check(m.lastAttack().finalDamage()==20&&m.activePokemonView(A).pokemonId().equals(old)!=use,"Strafe optional switch");}}
    static void landorus(){var m=StarterDeck100PokemonTest.game(232,1,id(1));var extra=StarterDeck100PokemonTest.hand(m,id(1));m.playBasicPokemonToBench(A,extra.instanceId());StarterDeck100PokemonTest.attack(m,1);var p=m.effectCardPrompt(A);check(p.minimum()==3&&p.maximum()==3,"all self Energy not mandatory");var before=m.clientView(A);TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),p.candidates().stream().limit(2).map(CardInstance::instanceId).toList()));check(before.equals(m.clientView(A)),"partial all-move mutated state");select(m,p.candidates());var move=m.effectAttachmentPrompt(A);check(m.hasPendingEnergyDistribution(),"all move missing distribution");var hosts=m.benchPokemonView(A);var source=m.activePokemonView(A).pokemonId();TopDeckLookTest.rejects(()->m.confirmEffectEnergyDistribution(A,move.resolutionId(),move.step()));for(int i=0;i<move.cards().size();i++){var c=move.cards().get(i);TopDeckLookTest.rejects(()->m.assignEffectEnergyDistribution(A,move.resolutionId(),move.step(),c.instanceId(),source));m.assignEffectEnergyDistribution(A,move.resolutionId(),move.step(),c.instanceId(),hosts.get(i%hosts.size()).pokemonId());}check(m.activePokemonView(A).attachedEnergyIds().size()==3,"draft assignments moved cards");m.confirmEffectEnergyDistribution(A,move.resolutionId(),move.step());check(m.activePokemonView(A).attachedEnergyIds().isEmpty()&&m.benchPokemonView(A).stream().mapToInt(v->v.attachedEnergyIds().size()).sum()==3,"all move lost or duplicated Energy");TopDeckLookTest.rejects(()->m.confirmEffectEnergyDistribution(A,move.resolutionId(),move.step()));}
    static void noBench(){var m=StarterDeck100PokemonTest.game(232);for(var v:List.copyOf(m.benchPokemonView(A))){m.knockOutPokemonByEffect(A,A,v.pokemonId());StarterDeck100CombatTest.settleKnockouts(m);}StarterDeck100PokemonTest.attack(m,1);check(!m.hasPendingCardSelection()&&!m.hasPendingAttachmentTarget()&&m.activePokemonView(A).attachedEnergyIds().size()==3,"no Bench must retain Energy and finish");}
    static void sandaconda(){var m=StarterDeck100PokemonTest.game(242,1,id(7),id(412));var extra=StarterDeck100PokemonTest.hand(m,id(7));m.playBasicPokemonToBench(A,extra.instanceId());var ss=StarterDeck100EnergyTest.attach(m,A,A,id(412),extra.instanceId());StarterDeck100PokemonTest.charge(m,1);var active=m.activePokemonView(A).pokemonId();var aEnergy=m.activePokemonView(A).attachedEnergyIds().getFirst();m.attack(A,"g-max-cyclone");var p=m.effectCardPrompt(A);var activeCard=p.candidates().stream().filter(c->c.instanceId().equals(aEnergy)).findFirst().orElseThrow();check(p.minimum()==0&&p.candidates().contains(ss),"any field Energy selection");select(m,List.of(activeCard,ss));var move=m.effectAttachmentPrompt(A);var before=m.clientView(A);TopDeckLookTest.rejects(()->m.assignEffectEnergyDistribution(B,move.resolutionId(),move.step(),ss.instanceId(),active));TopDeckLookTest.rejects(()->m.assignEffectEnergyDistribution(A,move.resolutionId(),move.step(),ss.instanceId(),m.activePokemonView(B).pokemonId()));TopDeckLookTest.rejects(()->m.assignEffectEnergyDistribution(A,move.resolutionId(),move.step(),ss.instanceId(),PokemonIdentityTestSupport.logical(m,A,extra.instanceId())));check(before.equals(m.clientView(A)),"invalid allocation mutated cards");m.assignEffectEnergyDistribution(A,move.resolutionId(),move.step(),ss.instanceId(),active);m.assignEffectEnergyDistribution(A,move.resolutionId(),move.step(),activeCard.instanceId(),PokemonIdentityTestSupport.logical(m,A,extra.instanceId()));m.confirmEffectEnergyDistribution(A,move.resolutionId(),move.step());check(m.privateView(A).discard().contains(ss)&&!m.activePokemonView(A).attachedEnergyIds().contains(ss.instanceId()),"invalid Single Strike host was not discarded");check(StarterDeck100PokemonTest.view(m,A,extra.instanceId()).attachedEnergyIds().equals(List.of(aEnergy))&&m.activePokemonView(A).attachedEnergyIds().size()==2,"swap consumed wrong Energy or unselected cards");}
    static void skip(){var m=StarterDeck100PokemonTest.game(242);StarterDeck100PokemonTest.attack(m,1);select(m,List.of());check(!m.hasPendingAttachmentTarget()&&m.activePokemonView(A).attachedEnergyIds().size()==3,"any Energy cannot choose zero");}
    static void pulse(){var m=StarterDeck100PokemonTest.game(242);StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==60&&m.benchPokemonView(B).getFirst().damage()==20,"Sand Pulse omitted Bench damage");}
}
